/* shared/store.js: demo state that carries over between the screens of a flow.
 *
 * Do not edit this file per screen (it is shared by every screen). It is copied from the skill by
 * `flow init` and is unit-tested there.
 *
 *   <script src="shared/data.js"></script>     sets window.PROTO_DATA = { start: {...}, story: { "<screen-id>": {...} } }
 *   <script src="shared/store.js"></script>    creates window.protoStore from it
 *
 *   protoStore.view('incident-detail')         the data to draw this screen with (start data + story for this screen
 *                                              + everything the viewer changed so far)
 *   protoStore.set('incidents.0.state', 'Resolved')       a data-changing action (the plan lists these)
 *   protoStore.update('cart.count', (n) => n + 1)
 *   ProtoStore.mount(protoStore, (store) => { ...draw the screen from store.view('<id>') ... })
 *                                              draws now, after every change, and again when the viewer comes back to
 *                                              the screen with the browser Back button (the page may be restored from
 *                                              memory with old data on it)
 *
 * State lives in the browser's session storage (one tab); if the browser blocks storage it lives in memory
 * (then each screen starts from the start data). Opening the entry screen as `<name>/?reset` clears it.
 */
(function (root) {
  'use strict';

  var KEY = 'proto-flow-state';

  function clone(x) {
    return x === undefined ? undefined : JSON.parse(JSON.stringify(x));
  }
  function isObject(x) {
    return x !== null && typeof x === 'object' && !Array.isArray(x);
  }
  function segments(path) {
    if (path === undefined || path === null || path === '') return [];
    return Array.isArray(path) ? path.map(String) : String(path).split('.');
  }
  function getPath(obj, path) {
    var cur = obj;
    var segs = segments(path);
    for (var i = 0; i < segs.length; i++) {
      if (cur === null || typeof cur !== 'object') return undefined;
      cur = cur[segs[i]];
    }
    return cur;
  }
  function setPath(obj, path, value) {
    var segs = segments(path);
    if (!segs.length) throw new Error('set needs a path');
    var cur = obj;
    for (var i = 0; i < segs.length - 1; i++) {
      var next = cur[segs[i]];
      if (next === null || typeof next !== 'object') {
        next = /^\d+$/.test(segs[i + 1]) ? [] : {};
        cur[segs[i]] = next;
      }
      cur = next;
    }
    cur[segs[segs.length - 1]] = value;
  }
  // Objects merge key by key; anything else (including a list) in the patch replaces what was there.
  function merge(base, patch) {
    if (!isObject(base) || !isObject(patch)) return patch === undefined ? base : clone(patch);
    var out = clone(base);
    Object.keys(patch).forEach(function (k) {
      out[k] = isObject(out[k]) && isObject(patch[k]) ? merge(out[k], patch[k]) : clone(patch[k]);
    });
    return out;
  }

  function memoryStorage() {
    var m = {};
    return {
      getItem: function (k) { return Object.prototype.hasOwnProperty.call(m, k) ? m[k] : null; },
      setItem: function (k, v) { m[k] = String(v); },
      removeItem: function (k) { delete m[k]; },
    };
  }
  function works(s) {
    try {
      s.setItem('__proto_probe', '1');
      s.removeItem('__proto_probe');
      return true;
    } catch (e) {
      return false;
    }
  }

  /**
   * create({ data, storage, key, search })
   *   data     window.PROTO_DATA: { start, story }
   *   storage  an object with getItem/setItem/removeItem (the browser's sessionStorage; injected so it can be tested).
   *            Missing or blocked -> memory.
   *   search   location.search; a "reset" parameter clears the saved state.
   */
  function create(opts) {
    opts = opts || {};
    var data = opts.data || {};
    var key = opts.key || KEY;
    var storage = opts.storage || null;
    var mode = 'session';
    if (!storage || !works(storage)) {
      storage = memoryStorage();
      mode = 'memory';
    }
    var listeners = [];
    var state;
    var touched = {}; // top-level keys the viewer has changed (kept with the state, so a story step never undoes an action)

    function fresh() {
      return clone(data.start) || {};
    }
    function load() {
      try {
        var raw = storage.getItem(key);
        var saved = raw ? JSON.parse(raw) : null;
        var ok = saved && saved.v === 1 && isObject(saved.state);
        state = ok ? saved.state : fresh();
        touched = ok && isObject(saved.touched) ? saved.touched : {};
      } catch (e) {
        state = fresh();
        touched = {};
      }
    }
    function save() {
      try {
        storage.setItem(key, JSON.stringify({ v: 1, state: state, touched: touched }));
      } catch (e) {
        // storage turned out unusable (blocked or full): keep going in memory
        storage = memoryStorage();
        mode = 'memory';
        try { storage.setItem(key, JSON.stringify({ v: 1, state: state, touched: touched })); } catch (e2) { /* nothing to do */ }
      }
    }
    function emit() {
      listeners.slice().forEach(function (fn) {
        try { fn(api); } catch (e) { if (root.console && root.console.error) root.console.error(e); }
      });
    }

    var resetRequested = /(^|[?&])reset(=|&|$)/.test(String(opts.search || ''));
    if (resetRequested) {
      try { storage.removeItem(key); } catch (e) { /* memory fallback below */ }
    }
    load();

    var api = {
      get mode() { return mode; },
      get resetRequested() { return resetRequested; },
      // a copy of a value in the current state (the whole state with no path)
      get: function (path) { return clone(getPath(state, path)); },
      // the data a screen draws: start data, this screen's story step, and then what the viewer changed
      view: function (screenId) {
        var story = (data.story && data.story[screenId]) || {};
        return merge(merge(fresh(), story), changedOnTop());
      },
      set: function (path, value) {
        setPath(state, path, clone(value));
        touched[segments(path)[0]] = true;
        save();
        emit();
      },
      update: function (path, fn) {
        api.set(path, fn(api.get(path)));
      },
      reset: function () {
        try { storage.removeItem(key); } catch (e) { /* ignore */ }
        touched = {};
        state = fresh();
        emit();
      },
      // read the saved state again (another screen may have changed it)
      reload: function () {
        load();
      },
      subscribe: function (fn) {
        listeners.push(fn);
        return function () { listeners = listeners.filter(function (f) { return f !== fn; }); };
      },
    };

    // What the viewer changed (whole top-level entries), re-applied on top of a screen's story step.
    function changedOnTop() {
      var out = {};
      Object.keys(touched).forEach(function (k) {
        if (state[k] !== undefined) out[k] = clone(state[k]);
      });
      return out;
    }
    return api;
  }

  /** mount(store, render): draw now (once the page is ready), after every change, and when the page is shown again. */
  function mount(store, render, env) {
    env = env || root;
    var doc = env.document;
    function show() { render(store); }
    if (doc && doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', show);
    else show();
    store.subscribe(show);
    if (env.addEventListener) {
      env.addEventListener('pageshow', function () {
        store.reload();
        show();
      });
    }
    return show;
  }

  root.ProtoStore = { create: create, mount: mount, merge: merge, version: 1 };

  // In a page: create window.protoStore from window.PROTO_DATA, and take "?reset" out of the address so a refresh keeps the state.
  if (typeof document !== 'undefined' && root.PROTO_DATA) {
    var session = null;
    try { session = root.sessionStorage; } catch (e) { session = null; }
    var search = (root.location && root.location.search) || '';
    root.protoStore = create({ data: root.PROTO_DATA, storage: session, search: search });
    if (root.protoStore.resetRequested && root.history && root.history.replaceState) {
      try {
        root.history.replaceState(null, '', root.location.pathname + search.replace(/([?&])reset(=[^&]*)?(&|$)/, function (_m, a, _b, c) { return c ? a : ''; }).replace(/^&/, '?'));
      } catch (e) { /* the address stays as it is */ }
    }
  }
})(typeof globalThis !== 'undefined' ? globalThis : this);
